mapper.select:

		SELECT
			bst.BOOKSET_ID as booksetId,/**账套代码**/
			fin.FINPROD_ID as finprodId,/**金融产品代码**/
			fin.VDATE as vdate,/**起息日**/
			fin.ACTMDATE as actMdate,/**实际到期日**/
			bst.STANDARD_CCY as standardCcy,/**本位币**/
			todo.BOOKSET_DATE as booksetDate,/**账套日期**/
			todo.BOOK_DATE as bookDate,/**入账日期**/
			todo.HAPPEN_DATE as happenDate, /**发生日期**/
			fin.P_FINPROD_ID as pfinprodId, /**母金融产品代码**/
			fin.profit_type as profitType /**收益类型**/
		FROM BOK_BOOKSET bst
		INNER JOIN BOK_BATCH_TASK_TODO todo ON bst.bookset_id = todo.bookset_id AND bst.ACCT_SUBJECT_TYPE = '01'
		INNER JOIN FIN_PRODUCT fin ON bst.ACCT_SUBJECT_ID = fin.FINPROD_ID AND fin.finprod_type = 'F16'
		WHERE  todo.SEQ_NO = #{seqNo}
			AND todo.BOOKSET_DATE = #{BOOKSET_DATE}
            AND todo.BOOK_DATE = #{BOOK_DATE}
            AND todo.HAPPEN_DATE = #{HAPPEN_DATE}
            AND todo.TASK_ID = #{taskId}
            AND fin.PROFIT_TYPE = #{profitType}   
            AND todo.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
